import java.util.*;
import java.io.*;

public class E1342_Variant3 {

    static long MOD = 998244353;

    static long fastPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long[] factorials, invFactorials;

    public static long binomial(long n, long k) {
        return factorials[(int) n] * invFactorials[(int) k] % MOD * invFactorials[(int) (n - k)] % MOD;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        long n = sc.nextInt();
        long k = sc.nextLong();

        if (k >= n) {
            pw.println(0);
            pw.close();
            return;
        }

        factorials = new long[(int) n + 1];
        invFactorials = new long[(int) n + 1];

        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (i * factorials[i - 1]) % MOD;
        }

        invFactorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            invFactorials[i] = (invFactorials[i - 1] * fastPow(i, MOD - 2)) % MOD;
        }

        long m = n - k;
        long sumPositive = 0, sumNegative = 0;

        for (int i = 0; i <= m; i++) {
            long term = (fastPow(m - i, n) * binomial(m, i)) % MOD;
            if (i % 2 == 0) {
                sumPositive = (sumPositive + term) % MOD;
            } else {
                sumNegative = (sumNegative + term) % MOD;
            }
        }

        long answer = (sumPositive - sumNegative + 2 * MOD) % MOD;
        answer = (answer * binomial(n, m)) % MOD;

        if (m != n) {
            answer = (answer * 2) % MOD;
        }

        pw.println(answer);
        pw.close();
    }
}
